def isolated_gap(below, c):
    # below is row r+1 list; gap at column c with value 0, isolated if neighbors are 8 (edges count as 8)
    if below[c]!=0: return False
    l = below[c-1] if c>0 else 8
    rr = below[c+1] if c<len(below)-1 else 8
    return l==8 and rr==8

def solve(g):
    H,W=len(g),len(g[0])
    src=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2][0]
    filled=[set() for _ in range(H)]
    filled[src[0]].add(src[1])
    for r in range(H):
        # vertical pass to next row
        if r+1<H:
            for c in filled[r]:
                if g[r+1][c]==0: filled[r+1].add(c)
        # horizontal spread on row r (using below row r+1)
        below = g[r+1] if r+1<H else None
        row=g[r]
        frontier=list(filled[r])
        while frontier:
            c=frontier.pop()
            for dc in (-1,1):
                nc=c+dc
                while 0<=nc<W and row[nc]==0 and nc not in filled[r]:
                    if below is None: break
                    b=below[nc]
                    if b==8:
                        filled[r].add(nc); frontier.append(nc); nc+=dc
                    elif b==0 and isolated_gap(below,nc):
                        filled[r].add(nc); break
                    else:
                        break
    return [[2 if c in filled[r] else g[r][c] for c in range(W)] for r in range(H)]

